import { useIntl } from 'react-intl';

import creativeDevelopmentImage from 'assets/img/ConnectionsCreativityOverview/creative_development.png';
import { SubPillarCard } from 'components';

import {
  StyledCreativeDevelopmentSection,
  StyledHowWeDoItImage,
} from './CreativeDevelopmentSection.styles';

export const CreativeDevelopmentSection = () => {
  const { formatMessage } = useIntl();

  return (
    <StyledCreativeDevelopmentSection data-testid="creative-development-section">
      <SubPillarCard
        title={formatMessage({
          id: 'ConnectionsCreativity.Home.creativeDevelopment.title',
        })}
        description={formatMessage({
          id: 'ConnectionsCreativity.Home.creativeDevelopment.description',
        })}
      >
        <StyledHowWeDoItImage
          data-testid="how-we-do-it-image"
          src={creativeDevelopmentImage}
          alt={formatMessage({
            id: 'ConnectionsCreativity.Home.creativeDevelopment.alt',
          })}
        />
      </SubPillarCard>
    </StyledCreativeDevelopmentSection>
  );
};
